it("guides a no-task project to deliver its existing direct commit, then points at the recorded conclusion", async () => {
  const { repo, head, stateDir } = workspace("direct-delivery");
  const installed = install(repo, stateDir);
  await start(installed, head, []);
  mkdirSync(join(repo, "deliverables"), { recursive: true });
  writeFileSync(join(repo, "deliverables", "package.md"), "# Package\n\nA directly committed deployment package.\n");
  execFileSync("git", ["add", "-A"], { cwd: repo });
  execFileSync("git", ["-c", "user.email=t@t.t", "-c", "user.name=t", "commit", "-qm", "package"], { cwd: repo });
  const direct = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();

  const before = (await call(installed, "palimpsest_work", { action: "readiness" })) as unknown as {
    action: string;
    reasons: string[];
    next: string[];
    task: unknown;
    directOutcome: { relation: string; repositoryHead: string | null; uncommittedPaths: string[] };
  };
  expect(before.action).toBe("SEMANTIC_JUDGEMENT");
  expect(before.task).toBeNull();
  expect(before.directOutcome).toMatchObject({ relation: "DIRECT_AHEAD", repositoryHead: direct, uncommittedPaths: [] });
  expect(before.reasons.join(" ")).toContain(direct);
  expect(before.reasons.join(" ")).toMatch(/direct commit|repository outcome/iu);
  expect(before.next.join(" ")).toContain("palimpsest_work action=conclude intent=DELIVER");
  expect(installed.controller.status().promotions).toEqual([]);

  const delivered = (await call(installed, "palimpsest_work", {
    action: "conclude",
    intent: "DELIVER",
    statement: "The directly committed package is the deliverable for this episode.",
    artifacts: ["deliverables/package.md"],
  })) as unknown as Conclude;
  expect(delivered.state).toBe("RECORDED");
  expect(delivered.session.mayEnd).toBe(true);

  // Re-reading the same position must point at the current conclusion, not restart planning.
  const after = (await call(installed, "palimpsest_work", { action: "readiness" })) as unknown as {
    action: string;
    reasons: string[];
    next: string[];
  };
  expect(after.action).toBe("SEMANTIC_JUDGEMENT");
  expect(after.next).toEqual(["reply using the recorded conclusion"]);
  expect(after.reasons.join(" ")).toMatch(/current recorded DELIVER conclusion/iu);
  expect(after.reasons.join(" ")).toContain(delivered.conclusion!.conclusionId);
  expect(installed.controller.status()).toMatchObject({ tasks: [], attempts: [], promotions: [] });
});

it("keeps unchanged and uncommitted no-task projects out of direct delivery", async () => {
  const { repo, head, stateDir } = workspace("direct-protection");
  const installed = install(repo, stateDir);
  await start(installed, head, []);

  const unchanged = (await call(installed, "palimpsest_work", { action: "readiness" })) as unknown as {
    action: string;
    reasons: string[];
    next: string[];
    directOutcome: { relation: string; uncommittedPaths: string[] };
  };
  expect(unchanged.action).toBe("CONTINUE_WORK");
  expect(unchanged.directOutcome).toMatchObject({ relation: "IN_SYNC", uncommittedPaths: [] });
  expect(unchanged.next.join(" ")).not.toContain("intent=DELIVER");

  mkdirSync(join(repo, "deliverables"), { recursive: true });
  writeFileSync(join(repo, "deliverables", "draft.md"), "# Draft\n\nNot committed yet.\n");
  const uncommitted = (await call(installed, "palimpsest_work", { action: "readiness" })) as unknown as {
    action: string;
    reasons: string[];
    next: string[];
    directOutcome: { relation: string; uncommittedPaths: string[] };
  };
  expect(uncommitted.action).toBe("CONTINUE_WORK");
  expect(uncommitted.directOutcome.relation).toBe("IN_SYNC");
  expect(uncommitted.directOutcome.uncommittedPaths).toContain("deliverables/draft.md");
  expect(uncommitted.next.join(" ")).not.toContain("intent=DELIVER");
});

